options.css:
@ .itemDetails {
	padding-left: 7px;
	display: grid;
}@ 

.itemDetails > .ellipse {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: pre-wrap;
	display: -webkit-box;
	-webkit-line-clamp: 1;
	-webkit-box-orient: vertical;
}@ 

.itemDetails > .supplier,@  .itemDetails > .supplier > p {
	overflow: hidden;
	text-overflow: ellipsis;
	display: flex;
}@ 

.itemDetails > .supplier > p {
	display: block;
}@

@ .receiptDetails {
	padding-left: 7px;
	display: grid;
}@ 

.receiptDetails .center {
	display: flex;
	align-items: center;
}@ 

.receiptDetails .receiptIcon {
	display: inline-flex;
	font-size: 1.4rem;
	margin-right: 4px;
}@

@ .statusDetails {
	padding-left: 7px;
	display: grid;
}@ 

.status {
	margin-left: 35%;
	width: fit-content;
	padding: 1px 5px;
	border-radius: 4px;
	display: grid;
}@ 

.status.error {
	color: var(--adminlist-cell-error-color);
	border: solid 1px var(--adminlist-cell-error-color);
	background: #FEE9EB;
}@ 

.status.warn {
	color: var(--adminlist-cell-warn-color);
	border: solid 1px var(--adminlist-cell-warn-color);
	background: #FFF0E6;
}@ 

.status.success {
	color: var(--adminlist-cell-success-color);
	border: solid 1px var(--adminlist-cell-success-color);
	background: rgba(94, 173, 37, 0.1);
}@ 

.budgetDetails {
	padding-left: 7px;
	width: fit-content;
	margin-left: auto;
	margin-right: auto;
}@ 

.budgetDetails .center {
	display: flex;
	align-items: center;
}@ 

.budgetIcon {
	display: inline-flex;
	font-size: 1.4rem;
	margin-right: 4px;
}@

@ .amountDetails {
	padding-left: 7px;
	display: grid;
	margin-right: 20px;
	text-align: right;
}@
